inline double landCoverage(double latitude, double longitude) noexcept
{
    const double wrapped = longitude - 360*std::floor((longitude+180)/360);
    const double x = (wrapped+180)*2-.5;
    const double y = std::clamp((90-latitude)*2-.5, 0., 359.);
    const int left = int(std::floor(x));
    const int top = int(std::floor(y));
    const double fx = x-left, fy = y-top;
    const auto sample = [](int column, int row) {
        column = (column+720)%720;
        row = std::min(row, 359);
        return double((landMask[row*12+column/64] >> (column%64)) & 1);
    };
    const double north = sample(left, top)*(1-fx) + sample(left+1, top)*fx;
    const double south = sample(left, top+1)*(1-fx) + sample(left+1, top+1)*fx;
    return north*(1-fy)+south*fy;
}

inline bool isLand(double latitude, double longitude) noexcept
{
    return landCoverage(latitude, longitude) >= .5;
}

